    // Load
    auto nMaxInteger = getInt(args, 0);
    if (nMaxInteger <= 0) {
        return Variable::ofInt(0);
    }

    // Transform

    // Execute
    return Variable::ofInt(randomInt(0, nMaxInteger - 1));
}

