    // Execute
    if (creatureToTakeFrom) {
        creatureToTakeFrom->takeGold(nAmount);
    }
    if (!destroy) {
        auto caller = checkCreature(getCaller(ctx));
        caller->giveGold(nAmount);
    }
    return Variable::ofNull();
}

